        resetEvolutionSettings: resetEvolutionSettings2,
        resetWarSettings: resetWarSettings2,
        resetHellSettings: resetHellSettings2,
        resetMechSettings: resetMechSettings2,
        resetFleetSettings: resetFleetSettings2,
